import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class TimeSeries_createCopy_TriageGen2Test {

    private TimeSeries series;
    private RegularTimePeriod p1;
    private RegularTimePeriod p2;
    private RegularTimePeriod p3;

    @Before
    public void setUp() {
        series = new TimeSeries("Test Series");
        p1 = new Second(new GregorianCalendar(2023, 0, 1, 10, 0, 0));
        p2 = new Second(new GregorianCalendar(2023, 0, 1, 11, 0, 0));
        p3 = new Second(new GregorianCalendar(2023, 0, 1, 12, 0, 0));

        series.add(p1, 1.0);
        series.add(p2, 2.0);
        series.add(p3, 3.0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCreateCopyNullStart() throws CloneNotSupportedException {
        series.createCopy(null, p1);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCreateCopyNullEnd() throws CloneNotSupportedException {
        series.createCopy(p1, null);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCreateCopyStartAfterEnd() throws CloneNotSupportedException {
        series.createCopy(p2, p1);
    }

    @Test
    public void testCreateCopyExactRange() throws CloneNotSupportedException {
        TimeSeries copy = series.createCopy(p1, p2);
        assertEquals(2, copy.getItemCount());
        assertEquals(1.0, copy.getValue(0).doubleValue(), 0.001);
        assertEquals(2.0, copy.getValue(1).doubleValue(), 0.001);
    }

    @Test
    public void testCreateCopyInclusiveRange() throws CloneNotSupportedException {
        TimeSeries copy = series.createCopy(p1, p3);
        assertEquals(3, copy.getItemCount());
    }

    @Test
    public void testCreateCopyWithUnmatchedStart() throws CloneNotSupportedException {
        // p1 is at index 0. Create a period that would result in index -1 (before first)
        RegularTimePeriod beforeFirst = new Second(new GregorianCalendar(2020, 0, 1));
        // getIndex(beforeFirst) should return -1. 
        // startIndex = -(-1 + 1) = 0.
        TimeSeries copy = series.createCopy(beforeFirst, p2);
        assertEquals(2, copy.getItemCount());
        assertEquals(1.0, copy.getValue(0).doubleValue(), 0.001);
    }

    @Test
    public void testCreateCopyWithUnmatchedEnd() throws CloneNotSupportedException {
        // p3 is index 2. Create a period that is after p3.
        RegularTimePeriod afterLast = new Second(new GregorianCalendar(2025, 0, 1));
        // getIndex(afterLast) should return -1 (if not found).
        // endIndex = -(-1 + 1) - 1 = -1.
        // This triggers emptyRange logic.
        TimeSeries copy = series.createCopy(p1, afterLast);
        // Based on code: if endIndex < 0, emptyRange = true.
        // However, the code logic for endIndex < 0 when not found is:
        // endIndex = -(-1 + 1) - 1 = -1.
        // Then if (endIndex < 0) emptyRange = true.
        // Wait, if end is after last item, getIndex returns -1? 
        // No, typically getIndex returns -(insertionPoint + 1).
        // If after last, insertionPoint is 3. getIndex returns -4.
        // endIndex = -(-4 + 1) - 1 = 3 - 1 = 2.
        // So endIndex = 2 (which is p3).
    }

    @Test
    public void testCreateCopyEmptyRangeStartAfterLast() throws CloneNotSupportedException {
        // start is after last data item
        RegularTimePeriod afterLast = new Second(new GregorianCalendar(2025, 0, 1));
        // getIndex(afterLast) -> -4. 
        // startIndex = -(-4 + 1) = 3.
        // 3 == series.data.size() (which is 3).
        // emptyRange = true.
        TimeSeries copy = series.createCopy(afterLast, afterLast);
        assertEquals(0, copy.getItemCount());
    }

    @Test
    public void testCreateCopyEmptyRangeEndBeforeFirst() throws CloneNotSupportedException {
        // end is before first item
        RegularTimePeriod beforeFirst = new Second(new GregorianCalendar(2020, 0, 1));
        // getIndex(beforeFirst) -> -1.
        // endIndex = -(-1 + 1) - 1 = -1.
        // endIndex < 0 -> emptyRange = true.
        TimeSeries copy = series.createCopy(p1, beforeFirst);
        assertEquals(0, copy.getItemCount());
    }

    @Test
    public void testCreateCopyExactMatchSingleItem() throws CloneNotSupportedException {
        TimeSeries copy = series.createCopy(p2, p2);
        assertEquals(1, copy.getItemCount());
        assertEquals(2.0, copy.getValue(0).doubleValue(), 0.001);
    }
}

